using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
internal static class LibraryStyle {
 internal static readonly Color Bg=Color.FromArgb(27,30,34),Surface=Color.FromArgb(39,43,48),Ink=Color.FromArgb(226,230,234),Muted=Color.FromArgb(151,160,169),Accent=Color.FromArgb(225,180,75);
 internal static readonly Font Font=new Font("Microsoft JhengHei UI",10);
 internal static void Form(Form form,string title,int width,int height){form.Text=title;form.ClientSize=new Size(width,height);form.BackColor=Bg;form.ForeColor=Ink;form.Font=Font;form.FormBorderStyle=FormBorderStyle.FixedSingle;form.MaximizeBox=false;form.StartPosition=FormStartPosition.CenterScreen;}
 internal static Label Label(Control parent,string text,int x,int y,int width,int height=24){var item=new Label{Text=text,Location=new Point(x,y),Size=new Size(width,height),ForeColor=Ink,AutoEllipsis=true,TextAlign=ContentAlignment.MiddleLeft};parent.Controls.Add(item);return item;}
 internal static Button Button(Control parent,string text,int x,int y,int width,EventHandler action){var item=new Button{Text=text,Location=new Point(x,y),Size=new Size(width,34),FlatStyle=FlatStyle.Flat,BackColor=Surface,ForeColor=Ink,UseVisualStyleBackColor=false};item.FlatAppearance.BorderColor=Color.FromArgb(65,71,78);item.Click+=action;parent.Controls.Add(item);return item;}
 internal static TextBox Input(Control parent,string text,int x,int y,int width,bool secret=false){var item=new TextBox{Text=text,Location=new Point(x,y),Width=width,BackColor=Surface,ForeColor=Ink,BorderStyle=BorderStyle.FixedSingle,UseSystemPasswordChar=secret};parent.Controls.Add(item);return item;}
}
internal sealed class LibraryWindow : Form {
 readonly Pet pet;readonly CancellationTokenSource lifetime=new CancellationTokenSource();CancellationTokenSource operation;LibraryClient client;TextBox address,key;Label network,details,pages;Button connect,upload,apply,previous,next;TabControl tabs;ListView local,shared;ImageList thumbnails;System.Windows.Forms.Timer health;bool busy,probing;int page,total,generation;readonly string cache=Path.Combine(Preferences.Folder,"Downloads");
 internal LibraryWindow(Pet pet){this.pet=pet;LibraryStyle.Form(this,"CornerPet | 素材庫",720,588);var options=LibraryOptions.Load();
  LibraryStyle.Label(this,"主機",16,14,52);address=LibraryStyle.Input(this,options.Address,70,14,330);LibraryStyle.Label(this,"密碼",414,14,52);key=LibraryStyle.Input(this,options.Key,468,14,236,true);
  connect=LibraryStyle.Button(this,"連線 / 重新整理",16,54,160,async(s,e)=>{try{if(tabs.SelectedIndex==0){Configure(true);tabs.SelectedIndex=1;}else await LoadPage(true);}catch(Exception ex){Net(Error(ex),true);}});
  upload=LibraryStyle.Button(this,"上傳素材",188,54,116,async(s,e)=>await Upload());LibraryStyle.Button(this,"啟動主機程式",316,54,152,(s,e)=>{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"CornerPet-LibraryHost.exe");try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,ex.Message,"主機啟動失敗");}});
  network=LibraryStyle.Label(this,"未連線",484,60,220);network.ForeColor=LibraryStyle.Muted;
  tabs=new TabControl{Location=new Point(16,104),Size=new Size(688,384)};var lp=new TabPage("本機已下載"){BackColor=LibraryStyle.Bg};var sp=new TabPage("共享素材"){BackColor=LibraryStyle.Bg};local=View(lp);shared=View(sp);tabs.TabPages.Add(lp);tabs.TabPages.Add(sp);Controls.Add(tabs);
  previous=LibraryStyle.Button(this,"上一頁",16,500,100,async(s,e)=>{if(page>0){page--;await LoadPage(false);}});next=LibraryStyle.Button(this,"下一頁",128,500,100,async(s,e)=>{page++;await LoadPage(false);});pages=LibraryStyle.Label(this,"",244,505,220);
  apply=LibraryStyle.Button(this,"套用",528,500,176,async(s,e)=>await Apply());details=LibraryStyle.Label(this,"共享庫每頁 12 筆，單檔上限 20 MB。",16,546,688);
  tabs.SelectedIndexChanged+=async(s,e)=>{page=0;await LoadPage(false);};health=new System.Windows.Forms.Timer{Interval=15000};health.Tick+=async(s,e)=>{if(busy||probing||client==null||tabs.SelectedIndex!=1||WindowState==FormWindowState.Minimized)return;probing=true;try{await client.Ping(lifetime.Token);Net("素材庫已連線",false);}catch(Exception ex){if(!IsDisposed&&!lifetime.IsCancellationRequested)Net(Error(ex),true);}finally{probing=false;}};Shown+=async(s,e)=>{health.Start();await LoadPage(false);};
 }
 ListView View(Control parent){var list=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.LargeIcon,MultiSelect=false,BackColor=LibraryStyle.Surface,ForeColor=LibraryStyle.Ink,BorderStyle=BorderStyle.None,HideSelection=false};list.SelectedIndexChanged+=(s,e)=>{var item=Selected();apply.Enabled=!busy&&item!=null;if(item!=null)details.Text=item.Name+"  /  "+item.Width+" × "+item.Height+"  /  "+item.Frames+" 幀  /  "+(item.Bytes/1024)+" KB";};parent.Controls.Add(list);return list;}
 ListView Current {get{return tabs.SelectedIndex==0?local:shared;}}
 AssetInfo Selected(){return Current.SelectedItems.Count==0?null:Current.SelectedItems[0].Tag as AssetInfo;}
 void Net(string text,bool error){network.Text=text;network.ForeColor=error?LibraryStyle.Accent:LibraryStyle.Muted;}
 int Begin(){if(operation!=null){operation.Cancel();operation.Dispose();}operation=CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token);busy=true;connect.Enabled=upload.Enabled=previous.Enabled=next.Enabled=apply.Enabled=tabs.Enabled=false;return ++generation;}
 void End(int id){if(IsDisposed||id!=generation||lifetime.IsCancellationRequested)return;busy=false;connect.Enabled=upload.Enabled=tabs.Enabled=true;previous.Enabled=page>0;next.Enabled=(page+1)*12<total;apply.Enabled=Selected()!=null;pages.Text=(page+1)+" / "+Math.Max(1,(total+11)/12)+" 頁 · "+total+" 筆";apply.Text=tabs.SelectedIndex==0?"套用":"下載並套用";}
 void Configure(bool save){if(client!=null)client.Dispose();client=new LibraryClient(address.Text,key.Text,cache);if(save){var options=new LibraryOptions{Address=address.Text.Trim()};options.Key=key.Text;options.Save();}}
 void ClearViews(){local.Items.Clear();shared.Items.Clear();local.LargeImageList=shared.LargeImageList=null;if(thumbnails!=null)thumbnails.Dispose();thumbnails=new ImageList{ImageSize=new Size(128,96),ColorDepth=ColorDepth.Depth32Bit};Current.LargeImageList=thumbnails;}
 async Task LoadPage(bool configure){if(IsDisposed||lifetime.IsCancellationRequested)return;int id=Begin();var token=operation.Token;try{
   AssetInfo[] items;if(tabs.SelectedIndex==0){items=LibraryClient.LocalPage(cache,page,out total);Net("本機素材可離線使用",false);}else{if(client==null||configure)Configure(configure);if(String.IsNullOrWhiteSpace(key.Text)){Net("請輸入共享密碼",true);total=0;ClearViews();return;}Net("連線中…",false);var response=await client.List(page,token);items=response.Items;total=response.Total;Net("素材庫已連線",false);}
   if(token.IsCancellationRequested||IsDisposed)return;ClearViews();foreach(var item in items)Current.Items.Add(new ListViewItem(item.Name){Tag=item});
   for(int i=0;i<items.Length;i++){byte[] bytes=null;string thumb=Path.Combine(cache,items[i].Id+".thumb.png");try{if(tabs.SelectedIndex==0){if(File.Exists(thumb)&&new FileInfo(thumb).Length<=262144)bytes=File.ReadAllBytes(thumb);}else bytes=await client.Thumbnail(items[i],token);if(token.IsCancellationRequested||IsDisposed)return;if(bytes!=null)using(var stream=new MemoryStream(bytes))using(var image=Image.FromStream(stream)){if(image.Width>160||image.Height>120)continue;thumbnails.Images.Add(image);Current.Items[i].ImageIndex=thumbnails.Images.Count-1;}}catch(OperationCanceledException){if(token.IsCancellationRequested)return;break;}catch{break;}}
   if(items.Length==0)details.Text=tabs.SelectedIndex==0?"尚無已下載素材。可從控制台匯入本機圖片。":"目前沒有共享素材，可按「上傳素材」加入。";
  }catch(Exception ex){if(!token.IsCancellationRequested&&!IsDisposed){Net(Error(ex),true);ClearViews();total=0;}}finally{End(id);}}
 async Task Upload(){if(busy)return;using(var picker=new OpenFileDialog{Filter="圖片|*.gif;*.png;*.jpg;*.jpeg;*.bmp",Title="上傳至共享素材庫"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;int id=Begin();bool success=false;try{Configure(true);Net("上傳中…",false);var item=await client.Upload(picker.FileName,operation.Token);Net("上傳完成",false);success=true;details.Text=item.Name;}catch(Exception ex){if(!IsDisposed&&!lifetime.IsCancellationRequested)Net(Error(ex),true);}finally{End(id);}if(success&&!IsDisposed){page=0;if(tabs.SelectedIndex==0)tabs.SelectedIndex=1;else await LoadPage(false);}}}
 async Task Apply(){var item=Selected();if(item==null||busy)return;int id=Begin();try{string path;if(tabs.SelectedIndex==0)path=Path.Combine(cache,item.Id+item.Extension);else{Net("下載中…",false);path=await client.Download(item,operation.Token);}if(lifetime.IsCancellationRequested||IsDisposed)return;pet.LoadImage(path);if(!pet.Visible)pet.Show();details.Text="已套用："+item.Name;Net(tabs.SelectedIndex==0?"本機素材可離線使用":"素材庫已連線",false);}catch(Exception ex){if(!IsDisposed&&!lifetime.IsCancellationRequested)Net(Error(ex),true);}finally{End(id);}}
 static string Error(Exception ex){if(ex is LibraryFailure||ex is ArgumentException||ex is InvalidDataException)return ex.Message;if(ex is HttpRequestException||ex is OperationCanceledException||ex is IOException)return "素材庫無法連線";return "操作失敗："+ex.Message;}
 bool cleaned;protected override void Dispose(bool disposing){if(disposing&&!cleaned){cleaned=true;lifetime.Cancel();if(health!=null){health.Stop();health.Dispose();}if(operation!=null){operation.Cancel();operation.Dispose();}if(client!=null)client.Dispose();if(local!=null)local.LargeImageList=null;if(shared!=null)shared.LargeImageList=null;if(thumbnails!=null)thumbnails.Dispose();}base.Dispose(disposing);}
}
